/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if(api.item && api.item.value) {
    if (api.item.value.open_new_window)
      return {"aria-label": helpers.translateSync("{0} - Link opens in a new tab.", api.item.value.title)};

    return {"aria-label":api.item.value.title};
  }
  else
    return {"aria-label": ""};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		items: [
			{
				id: 'cmdb_nlq_validation_error',
				status: 'critical',
				icon: 'info-circle-outline',
				content: event.payload.message,
				action: { type: 'dismiss' }
			}
		]
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
        route: 'smart-search-results',
        fields: {
            table: event.payload.table,
            listName: event.payload.userQuestion,
        },
        params: {
            encodedQuery: event.payload.encodedQuery ? event.payload.encodedQuery : null,
            nlqQueryLog: event.payload.nlqLogSysId ? event.payload.nlqLogSysId : null,
            savedQueryId: null,
            queryStatusId: null,
            modification: event.payload.modifiedUtterance ? event.payload.modifiedUtterance : null,
            outputSource: event.payload.outputSource ? event.payload.outputSource : null
        },
        redirect: null,
        passiveNavigation: null,
        title: event.payload.userQuestion,
        multiInstField: null,
        targetRoute: 'current',
        external: null
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  var importantActionCount = api.state.importantActions.length;
  if (importantActionCount === 1)
	  return helpers.translateSync("{0} important action", importantActionCount);
  return helpers.translateSync("{0} important actions", importantActionCount);
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		event: 'CMDB WS Home Important Action Card Button Clicked',
		value: {
			'Card Button Clicked': api.item.value.button.label
		}
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "whatsNewSelectedTime",
		value: event.payload.items[0]
	};
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var {
        data
    } = event.payload.payload;
    var {
        appServicesCategories
    } = api.state;
    var tab = 0;

    if (data['Group by'] && appServicesCategories.includes(data['Group by'])) {
        tab = appServicesCategories.indexOf(data['Group by']);
    }
    else if (data['elements'] && data['elements'].length === 1 && appServicesCategories.includes(data['elements'][0])) {
        tab = appServicesCategories.indexOf(data['elements'][0]);
    }
    return {
        route: 'application-services',
        fields: null,
        params: {
            "selectedTabIndex": tab.toString(),
            "ts": Date.now()
        },
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: 'current',
        external: null
    };
}
